// ---------------- 设备 ----------------

async function api(path, body) {
  const res = await fetch(path, body ? {
    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
  } : undefined);
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || ("HTTP " + res.status));
  return data;
}

async function eachLimit(items, limit, fn) {  // 简易并发窗口
  const queue = items.slice();
  await Promise.all(Array.from({ length: limit }, async () => {
    while (queue.length) await fn(queue.shift());
  }));
}

function makeRow(dev) {
  const row = el("div", "dev");
  const sub = el("div", "dev-sub", "读取状态…");
  const main = el("div", "dev-main");
  main.append(el("div", "dev-name", dev.name || dev.did), sub);

  const input = el("input");
  input.type = "checkbox";
  input.disabled = true;  // 状态没读到之前不给点
  const label = el("label", "switch");
  label.append(input, el("span", "track"));
  row.append(main, label);

  const desc = [dev.room, dev.model].filter(Boolean).join(" · ");
  // 出错的原文（未能定位主开关那条尤其长）塞进 title，行内只留一句短的
  const note = (text, isErr, full) => {
    sub.textContent = text;
    sub.className = "dev-sub" + (isErr ? " err" : "");
    sub.title = full || "";
  };

  const load = async () => {
    try {
      const { power } = await api("/device/power?did=" + encodeURIComponent(dev.did));
      if (power === null) { note("读不到开关状态", true); return; }
      input.checked = power;
      input.disabled = false;
      note(desc);
    } catch (e) {
      // 传感器、网关、摄像头自己都没有可写的 on 属性，在列表里还占多数，这是常态不是故障
      note(e.message.includes("未能定位主开关") ? "不支持开关" : e.message, true, e.message);
    }
  };

  input.onchange = async () => {
    const want = input.checked;
    input.disabled = true;
    note(want ? "打开中…" : "关闭中…");
    try {
      const { power } = await api("/device/power", { did: dev.did, action: want ? "on" : "off" });
      input.checked = !!power;  // 以回读的真实状态为准，而不是以点了什么为准
      note(desc);
    } catch (e) {
      input.checked = !want;
      note(e.message, true, e.message);
    }
    input.disabled = false;
  };

  return { row, load };
}

async function loadDevices() {
  const box = $("#devices");
  const btn = $("#refresh");
  btn.disabled = true;
  box.replaceChildren(el("div", "empty", "加载中…"));
  $("#count").textContent = "";

  let devices;
  try {
    devices = await api("/devices");
  } catch (e) {
    box.replaceChildren(el("div", "empty err", "设备列表加载失败：" + e.message));
    btn.disabled = false;
    return;
  }
  if (!devices.length) {
    box.replaceChildren(el("div", "empty", "暂无在线设备"));
    btn.disabled = false;
    return;
  }

  const rows = devices.map(makeRow);
  box.replaceChildren(...rows.map((r) => r.row));
  $("#count").textContent = devices.length + " 台在线";
  // 每台设备的状态都是一次米家云请求，首次还要拉 spec（超时 10s）。全部并发发出去会占满
  // 服务端线程池，板子上还得给视频流留 CPU，所以限 3 路。
  await eachLimit(rows, 3, (r) => r.load());
  btn.disabled = false;
}

$("#refresh").onclick = loadDevices;
loadDevices();
</script>
</body>
</html>
